/**
 * Phase 4, plus a way in.
 *
 * Everything under here has been real since Phase 3 — the store, the applier,
 * the view models, the seeded dice, the stage machine. Phase 4 made the last
 * two fakes real: the dungeon is generated by the pipeline rather than read
 * from a fixture, and the referee is the model rather than a keyword table.
 *
 * What is new is the front of the app. A bare load lands on `Characters`, goes
 * to `RunSetup`, and generation starts when the player confirms — rather than
 * on mount, from whatever the URL happened to say.
 *
 * The dev switches still bypass all of that, because interface work against a
 * real dungeon is unbearable if every iteration costs two clicks and a minute:
 *
 *   ?offline=1   the fixture dungeon. Free and instant, for interface work.
 *   ?stub=1      the Phase 3 referee. Spends no tokens at all.
 *   ?seed=       which dungeon. Same seed, same dungeon.
 *   ?size=1..5   how big. Each region is one content-pass call.
 *   ?level=      how dangerous.
 *
 * Any one of those present means: skip the front, generate immediately with
 * the first saved character, exactly as this file behaved before. With none of
 * them, a fresh load costs a minute and real tokens, which is why they exist.
 *
 * Every run writes itself down. The journal goes to `out/runs/<run id>/` by way
 * of the dev server — see the plugin in vite.config.ts — and holds the dungeon,
 * every prompt and response, every roll, and every change to the world.
 */

import { useEffect, useMemo, useRef, useState } from "react";
import { PlayScreen } from "./ui/play/PlayScreen.tsx";
import { LoadingScreen } from "./ui/LoadingScreen.tsx";
import { Characters } from "./ui/Characters.tsx";
import { RunSetup } from "./ui/RunSetup.tsx";
import { toItems } from "./ui/play/Narration.tsx";
import { useGame } from "./store/game.ts";
import { listCharacters } from "./store/characters.ts";
import { createTurnMachine, type TurnMachine } from "./runtime/turn.ts";
import { createModelReferee } from "./runtime/referee.ts";
import { generateDungeon, type GenerationProgress } from "./runtime/generate.ts";
import { stubReferee } from "./runtime/__fixtures__/stub-referee.ts";
import { generateOffline } from "./runtime/__fixtures__/offline.ts";
import { attach, log, runId } from "./runtime/journal.ts";
import { randomSeed } from "./runtime/seeds.ts";
import { httpSink } from "./runtime/journal-http.ts";
import { MODELS } from "./runtime/llm/models.ts";
import type { PlayerCharacter, Size } from "./engine/index.ts";

const params = new URLSearchParams(location.search);
const OFFLINE = params.get("offline") === "1";
const STUB = params.get("stub") === "1";

/** Any dev switch at all means the front of the app is not what you came for. */
const BYPASS = ["seed", "size", "level", "offline", "stub"].some((k) => params.has(k));

const SEED = Number(params.get("seed") ?? 1005);
const SIZE = (Number(params.get("size") ?? 2) as Size) ?? 2;
const LEVEL = Number(params.get("level") ?? 1);

/**
 * A run started from the front of the app gets a fresh dungeon unless the URL
 * pinned one. The bypass path keeps its 1005 default, so `?stub=1` on its own
 * still returns to the same dungeon every time — which is the whole point of
 * it during interface work.
 */
const seedForNewRun = () => (params.has("seed") ? SEED : randomSeed());

/** Only the part before a run. Once the dungeon exists, that is what decides. */
type Screen = "characters" | "setup" | "generating";

interface Begin {
  seed: number;
  size: Size;
  level: number;
  character: PlayerCharacter;
}

export default function App() {
  const { dungeon, run } = useGame();
  const machine = useRef<TurnMachine>(null);
  const started = useRef(false);
  const [screen, setScreen] = useState<Screen>(BYPASS ? "generating" : "characters");
  const [characters, setCharacters] = useState<PlayerCharacter[]>();
  const [progress, setProgress] = useState<GenerationProgress>();
  const [error, setError] = useState<string>();

  async function begin({ seed, size, level, character }: Begin) {
    // Guards the double-invoke of StrictMode's development mount. It mattered
    // in Phase 3 because two room entries would describe the same room twice;
    // it matters more now, because it would generate the whole dungeon twice.
    if (started.current) return;
    started.current = true;
    setScreen("generating");
    const turn = createTurnMachine(STUB ? stubReferee : createModelReferee());
    machine.current = turn;

    const id = runId(seed);
    attach(httpSink(id));

    try {
      // First line of the file, before anything can go wrong — a run that
      // fails during generation is a run worth reading.
      log({
        kind: "run",
        runId: id,
        seed,
        size,
        level,
        offline: OFFLINE,
        models: MODELS,
        character,
      });

      const gd = OFFLINE
        ? generateOffline(seed, size)
        : await generateDungeon({ seed, size, level, onProgress: setProgress });

      useGame.getState().start(gd, character);
      await turn.enterRoom();
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e);
      log({ kind: "error", where: "app", message });
      setError(message);
    }
  }

  useEffect(() => {
    void (async () => {
      const cs = await listCharacters();
      setCharacters(cs);
      if (BYPASS && cs[0]) {
        void begin({ seed: SEED, size: SIZE, level: LEVEL, character: cs[0] });
      }
    })();
  }, []);

  const items = useMemo(() => {
    if (!run) return [];
    const name = (id: string) => run.entities.rooms.find((r) => r.id === id)?.name ?? "Somewhere";
    const pass = useGame.getState().dungeon?.pass;
    return toItems(run.log, name, pass && { name: pass.name, objective: pass.goal.summary });
  }, [run?.log]);

  if (error) {
    return (
      <div className="p-8 font-mono text-sm text-torch">
        Could not build a dungeon: {error}
      </div>
    );
  }

  if (screen === "characters") {
    return <Characters characters={characters} onStartRun={() => setScreen("setup")} />;
  }

  if (screen === "setup") {
    return (
      <RunSetup
        characters={characters ?? []}
        onBack={() => setScreen("characters")}
        onConfirm={({ size, level, character }) =>
          void begin({ seed: seedForNewRun(), size, level, character })
        }
      />
    );
  }

  if (!dungeon || !run) {
    return <LoadingScreen progress={progress} />;
  }

  return (
    <PlayScreen
      dungeon={dungeon}
      run={run}
      items={items}
      onSubmit={(text) => void machine.current?.submit(text)}
      onRoll={() => void machine.current?.roll()}
      onRetry={() => void machine.current?.retry()}
    />
  );
}
